"""Dewey Decimal Classification (DDC 23) Detailed Schedules & Inclusions.

Provides full disciplinary schedule trees, scope annotations, and classification instructions.
"""

from typing import Dict, List, Optional
from dataclasses import dataclass, field


@dataclass
class DdcScheduleEntry:
    notation: str
    caption: str
    hierarchy_level: int
    scope_notes: str
    class_here: List[str] = field(default_factory=list)
    do_not_use: Optional[str] = None


DDC_SCHEDULE_MAP: Dict[str, DdcScheduleEntry] = {}

def _sched(notation: str, caption: str, level: int, notes: str, class_here: List[str] = None):
    DDC_SCHEDULE_MAP[notation] = DdcScheduleEntry(
        notation=notation,
        caption=caption,
        hierarchy_level=level,
        scope_notes=notes,
        class_here=class_here or []
    )

