def get_ddc_schedule(notation: str) -> Optional[DdcScheduleEntry]:
    return DDC_SCHEDULE_MAP.get(notation.strip()[:3])

def get_child_schedules(parent_prefix: str) -> List[DdcScheduleEntry]:
    return [
        entry for notat, entry in DDC_SCHEDULE_MAP.items()
        if notat.startswith(parent_prefix) and notat != parent_prefix
    ]
